SELECT id, kanji, kana, meaning, point_code FROM (SELECT id, kanji, kana, meaning, point_code, trim(CASE WHEN COALESCE(meaning,'') GLOB '[[]N[1-5]]*' THEN substr(meaning,5) ELSE COALESCE(meaning,'') END, ' ' || char(9) || char(10) || char(13) || char(160) || char(12288)) AS bare FROM vocab_word WHERE subject_id = CAST(:subject_id AS INTEGER)) WHERE (CASE WHEN :direction = 'kanji2kana' THEN COALESCE(kanji,'') <> '' AND kanji <> COALESCE(kana,'') ELSE COALESCE(meaning,'') <> '' END) AND (:level = '' OR substr(COALESCE(meaning,''), 1, length(:level) + 2) = '[' || :level || ']') AND (:only_ids = '' OR id IN (SELECT value FROM json_each('[' || :only_ids || ']'))) AND (:skip_ids = '' OR id NOT IN (SELECT value FROM json_each('[' || :skip_ids || ']'))) AND COALESCE(point_code,'') NOT IN ('hiragana','katakana','youon','dakuon','potential','volitional','imperative','causative','causative-passive','counters-sound') AND bare <> '' AND (' ' || bare) NOT GLOB '*[^ ] 的*' AND bare NOT LIKE '%的礼貌形' ORDER BY CASE WHEN :only_ids = '' THEN id ELSE instr(',' || :only_ids || ',', ',' || id || ',') END, id
